  const aboutStyle=document.createElement('style');aboutStyle.textContent='.about-dialog{box-sizing:border-box;width:min(500px,92vw);max-width:92vw;padding:0;border:1px solid #aeb8c4;border-radius:9px;background:var(--card,#fff);color:var(--text,#111827);font:13px "Segoe UI",sans-serif;box-shadow:0 18px 50px #0004}.about-dialog::backdrop{background:#11182788;backdrop-filter:blur(1px)}.about-dialog>header{display:flex;align-items:center;justify-content:space-between;padding:10px 14px;border-bottom:1px solid var(--border,#d5dbe3);font-size:13px}.about-dialog .about-close{width:28px;height:28px;border:0;border-radius:5px;background:transparent;color:inherit;font-size:22px;line-height:1;cursor:pointer}.about-dialog .about-close:hover{background:#e8edf2}.about-brand{display:flex;align-items:center;justify-content:center;gap:14px;padding:28px 20px;background:#eef1f3}.about-logo{width:62px;height:62px;flex:none}.about-logo svg{display:block;width:100%;height:100%}.about-wordmark{display:flex;align-items:baseline;gap:10px;color:#1f2937}.about-wordmark strong{font-size:34px;letter-spacing:.02em}.about-wordmark span{font-size:30px;font-weight:600;color:#168348}.about-dialog main{padding:18px 30px 8px}.about-description{margin:0 0 16px;font-size:14px;font-weight:600}.about-dialog dl{display:grid;grid-template-columns:100px 1fr;gap:9px;margin:0;padding:0 0 15px;border-bottom:1px solid var(--border,#d5dbe3)}.about-dialog dt{color:var(--muted,#64748b)}.about-dialog dd{margin:0;font-weight:600}.about-note{margin:13px 0 5px;color:var(--muted,#64748b);font-size:12px}.about-dialog>footer{display:flex;justify-content:flex-end;padding:12px 20px 18px}.about-dialog .about-ok{min-width:82px;padding:7px 16px;border:1px solid #15803d;border-radius:5px;background:#16a34a;color:#fff;font:inherit;cursor:pointer}.about-dialog .about-ok:hover{background:#15803d}@media(max-width:480px){.about-dialog main{padding:16px}.about-wordmark strong{font-size:27px}.about-wordmark span{font-size:23px}}';doc